import{_ as l,C as a,o as r,c,a2 as s,E as i,j as o,a as t}from"./chunks/framework.D66Xq0Kv.js";const g="/assets/collections-list.DM4Eq6Kf.png",h="/assets/collection-form.S34A3eer.png",k=JSON.parse('{"title":"Collections","description":"","frontmatter":{},"headers":[],"relativePath":"collections.md","filePath":"collections.md"}'),d={name:"collections.md"},p={id:"sharing-collections",tabindex:"-1"};function u(m,e,f,C,w,y){const n=a("Badge");return r(),c("div",null,[e[3]||(e[3]=s('<h1 id="collections" tabindex="-1">Collections <a class="header-anchor" href="#collections" aria-label="Permalink to &quot;Collections&quot;">​</a></h1><p>Collections are groupings for assets. You must have at least one collection in order to add assets.</p><h2 id="managing-collections" tabindex="-1">Managing Collections <a class="header-anchor" href="#managing-collections" aria-label="Permalink to &quot;Managing Collections&quot;">​</a></h2><p>Open the main menu and choose <strong>Admin</strong> › <strong>Edit Collections</strong>. In a wide window, you can also choose <strong>Collections</strong> in the sidebar on admin pages. Administrators also see a <strong>Manage Collections</strong> button on the All Collections browse page.</p><p><img src="'+g+'" alt="The Collections page, listing four collections with their parent and whether they appear on the browse page"></p><p>The <strong>Collections</strong> page lists every collection in the instance, its parent, and whether it appears on the Browse Collections page (<strong>In Browse</strong>). Each row&#39;s <strong>⋮</strong> menu has <strong>Edit</strong>, <strong>Permissions</strong>, and <strong>Delete</strong>. See <a href="/permissions.html">Permissions</a> for collection permissions.</p><h2 id="creating-a-collection" tabindex="-1">Creating a Collection <a class="header-anchor" href="#creating-a-collection" aria-label="Permalink to &quot;Creating a Collection&quot;">​</a></h2><p>To create a collection, click <strong>Create Collection</strong>, fill in the form, and click <strong>Create</strong>. When editing an existing collection, the button is <strong>Save</strong>.</p><p><img src="'+h+'" alt="The Create Collection form, with Bucket Settings expanded"></p><p>Generally, you’ll only need to populate the <strong>Title</strong> for your collection.</p><p>Collections can be nested within other collections by choosing a <strong>Parent</strong>, or <strong>None (top level)</strong> for a top-level collection. They will be grouped hierarchically in dropdowns and in the collection browsing interface.</p><p><strong>Show on Browse Collections Page</strong> controls whether the collection is listed on the All Collections page and in its parent collection’s list of sub-collections.</p><p>You can attach a <strong>Description</strong> which will be displayed when browsing the collections on your instance. You can also add a <strong>Preview Image File ID</strong>, the ID of an uploaded file within your site, whose image is shown on the browse page. To find a file’s ID, open its asset, click the pencil icon (<strong>Edit Asset</strong>), and click the arrow on the file’s entry to show its details. The ID is listed as <strong>File ID</strong>.</p><h3 id="storage" tabindex="-1">Storage <a class="header-anchor" href="#storage" aria-label="Permalink to &quot;Storage&quot;">​</a></h3><p>If you’d like this collection stored in a separate location in the cloud, open <strong>Bucket Settings</strong> and fill in <strong>S3 Key</strong>, <strong>S3 Secret</strong>, <strong>Bucket</strong>, and <strong>Bucket Region</strong>. When you create a collection, fields left empty are filled with your instance’s current settings (shown as &quot;Instance default&quot;). After that, the collection keeps its own copy: changing the instance’s settings later doesn’t change it, and clearing a field while editing leaves the stored value in place.</p><p>Sometimes you may wish to use a separate bucket for a given collection. For example, you may have most of your collections to automatically migrate original files to “glacier” storage, which is much less expensive, but much slower to access. You may then wish to keep one collection’s original assets always available.</p>',16)),i(n,{type:"info",text:"Classic UI"}),e[4]||(e[4]=s(" To create a new bucket, open <strong>Admin</strong> › <strong>Edit Collections (Classic)</strong> and edit the collection. Click <strong>Show Bucket Options</strong>, clear the <strong>Bucket</strong> and <strong>S3 Key</strong> fields, and click <strong>Create new bucket</strong>. Fill in the <strong>Create an S3 Bucket</strong> dialog, click <strong>Create Bucket</strong>, and then save the collection.",17)),o("h2",p,[e[0]||(e[0]=t("Sharing Collections ",-1)),i(n,{type:"info",text:"Classic UI"}),e[1]||(e[1]=t()),e[2]||(e[2]=o("a",{class:"header-anchor",href:"#sharing-collections","aria-label":'Permalink to "Sharing Collections <Badge type="info" text="Classic UI" />"'},"​",-1))]),e[5]||(e[5]=o("p",null,"Collections may be shared between instances. By sharing a collection, you’ll be granting the receiving instance’s admin full power over your collection.",-1)),e[6]||(e[6]=o("p",null,[t("Open "),o("strong",null,"Admin"),t(" › "),o("strong",null,"Edit Collections (Classic)"),t(" and click "),o("strong",null,"Share"),t(" next to the collection.")],-1))])}const _=l(d,[["render",u]]);export{k as __pageData,_ as default};
